3	pub fn write_delegate(item: &metadata::reader::TypeDef) -> Result<TokenStream, Error> {
4	    let namespace = item.namespace();
5	    let name = write_ident(item.name());
6	
7	    let (generics, generics_tokens) = write_generic_params(item);
8	
9	    let method = item
10	        .methods()
11	        .find(|method| method.name() == "Invoke")
12	        .ok_or_else(|| writer_err!("delegate `{}` has no `Invoke` method", item.name()))?;
13	
14	    let signature = method.signature(&generics);
15	    let return_type = write_return_type(namespace, &method, &signature)?;
16	    let params = write_params(namespace, &method, signature.types)?;
17	
18	    let guid_token = match delegate_guid_output(item, &generics)? {
19	        GuidOutput::None => quote! { #[no_guid] },
20	        GuidOutput::Omit => quote! {},
21	        GuidOutput::Explicit(d1, d2, d3, d4) => {
22	            let lit = syn::LitInt::new(&format_guid_u128(d1, d2, d3, d4), Span::call_site());
23	            quote! { #[guid(#lit)] }
24	        }
25	    };
26	    let custom_attrs = write_custom_attributes_except(
27	        item.attributes(),
28	        namespace,
29	        item.index(),
30	        &["GuidAttribute", "UnmanagedFunctionPointerAttribute"],
31	    )?;
32	
33	    let abi = match read_unmanaged_abi(item) {
34	        None => None,
35	        Some(1) => Some("system"),
36	        Some(2) => Some("C"),
37	        Some(5) => Some("fastcall"),
38	        Some(n) => {
39	            return Err(writer_err!(
40	                "unexpected CallingConvention value {n} in `UnmanagedFunctionPointerAttribute`"
41	            ))
42	        }
43	    };
44	
45	    Ok(quote! {
46	        #guid_token
47	        #(#custom_attrs)*
48	        delegate #abi fn #name #generics_tokens (#(#params),*) #return_type;
49	    })
50	}
