use super::*;

syn::custom_keyword!(interface);
syn::custom_keyword!(event);

#[derive(Debug)]
pub struct Interface {
    pub attrs: Vec<syn::Attribute>,
    pub token: interface,
    pub name: syn::Ident,
    pub generics: syn::Generics,
    pub requires: Vec<syn::Path>,
    pub members: Vec<InterfaceMember>,
    pub winrt: bool,
}

/// A single member appearing inside an interface body.
#[derive(Debug)]
pub enum InterfaceMember {
    Method(Method),
    Property(Property),
    Event(Event),
}

/// A property shorthand declaration inside an interface body.
///
/// Parsed from `[#[get] | #[set]] Name: Type;`.  Without any attribute both a
/// getter and a setter are generated; with `#[get]` only a getter is generated;
/// with `#[set]` only a setter is generated.
#[derive(Debug)]
pub struct Property {
    pub attrs: Vec<syn::Attribute>,
    pub name: syn::Ident,
    pub ty: syn::Type,
}

/// An event shorthand declaration inside a WinRT interface body.
///
/// Parsed from `event Name: HandlerType;`.  Generates `add_Name` and
/// `remove_Name` method pairs with the `SpecialName` flag.
#[derive(Debug)]
pub struct Event {
    pub name: syn::Ident,
    pub handler_ty: syn::Type,
}

impl syn::parse::Parse for InterfaceMember {
    fn parse(input: syn::parse::ParseStream) -> syn::Result<Self> {
        let attrs = input.call(syn::Attribute::parse_outer)?;

        // `event Name: HandlerType;` — an `event` keyword immediately followed by
        // an identifier.  `event: Type;` (a property literally named `event`) is
        // still treated as a property because the keyword is followed by `:`.
        if input.peek(event) && input.peek2(syn::Ident) {
            input.parse::<event>()?;
            let name = input.parse()?;
            input.parse::<syn::Token![:]>()?;
            let handler_ty = input.parse()?;
            input.parse::<syn::Token![;]>()?;
            return Ok(InterfaceMember::Event(Event { name, handler_ty }));
        }

        // `fn Name(...) ...;` — a regular method.
        if input.peek(syn::Token![fn]) {
            return Ok(InterfaceMember::Method(Method::parse_rest(input, attrs)?));
        }

        // Otherwise a property shorthand: `Name: Type;`.
        let name = input.parse()?;
        input.parse::<syn::Token![:]>()?;
        let ty = input.parse()?;
        input.parse::<syn::Token![;]>()?;
        Ok(InterfaceMember::Property(Property { attrs, name, ty }))
    }
}

impl syn::parse::Parse for Interface {
    fn parse(input: syn::parse::ParseStream) -> syn::Result<Self> {
        let attrs = input.call(syn::Attribute::parse_outer)?;
