        item.attributes(),
        namespace,
        item.index(),
        &["GuidAttribute"],
    )?;

    Ok(quote! {
        #guid_token
        #(#custom_attrs)*
        interface #name #generics_tokens #requires_tokens {
            #(#methods)*
        }
    })
