/// Emits all interface members, converting `SpecialName` getter/setter pairs to
/// property shorthand and `add_`/`remove_` pairs to event shorthand, and falling
/// back to the regular method representation for anything not converted.
fn write_members(
    namespace: &str,
    item: &metadata::reader::TypeDef,
    generics: &[metadata::Type],
) -> Result<Vec<TokenStream>, Error> {
    let winrt = item
        .flags()
        .contains(metadata::TypeAttributes::WindowsRuntime);
    let methods: Vec<metadata::reader::MethodDef> = item.methods().collect();
    let mut consumed = vec![false; methods.len()];
    let mut result = Vec::new();

    // A method is only eligible for shorthand conversion when it is `SpecialName`
    // and carries no custom attributes (which the shorthand syntax cannot express).
    let has_no_custom_attrs = |method: &metadata::reader::MethodDef| -> Result<bool, Error> {
        Ok(write_custom_attributes(method.attributes(), namespace, item.index())?.is_empty())
    };
    let is_special = |method: &metadata::reader::MethodDef| {
        method
            .flags()
            .contains(metadata::MethodAttributes::SpecialName)
    };

    for i in 0..methods.len() {
        if consumed[i] {
            continue;
        }

        let method = &methods[i];
        let name = method.name();

        if is_special(method) && has_no_custom_attrs(method)? {
            // Property getter: `get_X` (optionally paired with `put_X`).
            if let Some(prop) = name.strip_prefix("get_") {
                consumed[i] = true;
                let ty = method.signature(generics).return_type;
                let setter = find_pair(&methods, &consumed, i, &format!("put_{prop}"), &has_no_custom_attrs)?;
                if let Some(j) = setter {
                    consumed[j] = true;
                    result.push(write_property(prop, &ty, namespace, PropertyKind::Both));
                } else {
                    result.push(write_property(prop, &ty, namespace, PropertyKind::Get));
                }
                continue;
            }

            // Property setter reached before/without its getter: `put_X`.
            if let Some(prop) = name.strip_prefix("put_") {
                consumed[i] = true;
                let getter = find_pair(&methods, &consumed, i, &format!("get_{prop}"), &has_no_custom_attrs)?;
                if let Some(j) = getter {
                    consumed[j] = true;
                    let ty = methods[j].signature(generics).return_type;
                    result.push(write_property(prop, &ty, namespace, PropertyKind::Both));
                } else if let Some(ty) = method.signature(generics).types.into_iter().next() {
                    result.push(write_property(prop, &ty, namespace, PropertyKind::Set));
                } else {
                    // Malformed setter with no parameter — emit as a plain method.
                    result.push(write_method(namespace, method, generics)?);
                }
                continue;
            }

            if winrt {
                // Event: `add_X` (optionally paired with `remove_X`).
                if let Some(ev) = name.strip_prefix("add_") {
                    if let Some(handler) = method.signature(generics).types.into_iter().next() {
                        consumed[i] = true;
                        if let Some(j) =
                            find_pair(&methods, &consumed, i, &format!("remove_{ev}"), &has_no_custom_attrs)?
                        {
                            consumed[j] = true;
                        }
                        result.push(write_event(ev, &handler, namespace));
                        continue;
                    }
                }

                // Event remove reached before/without its add: `remove_X`.
                if let Some(ev) = name.strip_prefix("remove_") {
                    if let Some(j) =
                        find_pair(&methods, &consumed, i, &format!("add_{ev}"), &has_no_custom_attrs)?
                    {
                        if let Some(handler) = methods[j].signature(generics).types.into_iter().next() {
                            consumed[i] = true;
                            consumed[j] = true;
                            result.push(write_event(ev, &handler, namespace));
                            continue;
                        }
                    }
                }
            }
        }

        consumed[i] = true;
        result.push(write_method(namespace, method, generics)?);
    }

    Ok(result)
}

/// Finds the index of an unconsumed method with the given name, searching forward
/// from `from` (wrapping around).  Only methods satisfying `eligible` are returned.
fn find_pair(
    methods: &[metadata::reader::MethodDef],
    consumed: &[bool],
    from: usize,
    name: &str,
    eligible: &impl Fn(&metadata::reader::MethodDef) -> Result<bool, Error>,
) -> Result<Option<usize>, Error> {
    if let Some(index) = find_unconsumed(methods, consumed, from, name) {
        if eligible(&methods[index])? {
            return Ok(Some(index));
        }
    }
    Ok(None)
}

/// Finds the index of an unconsumed method with the given name, searching forward
/// from `from` (wrapping around).  Used to locate paired `get_`/`put_` or
/// `add_`/`remove_` methods.
fn find_unconsumed(
    methods: &[metadata::reader::MethodDef],
    consumed: &[bool],
    from: usize,
    name: &str,
) -> Option<usize> {
    let len = methods.len();
    for offset in 1..=len {
        let index = (from + offset) % len;
        if !consumed[index] && methods[index].name() == name {
            return Some(index);
        }
    }
    None
}

enum PropertyKind {
    Both,
    Get,
    Set,
}

fn write_property(
    name: &str,
    ty: &metadata::Type,
    namespace: &str,
    kind: PropertyKind,
) -> TokenStream {
    let name = write_ident(name);
    let ty = write_type(namespace, ty);
    match kind {
        PropertyKind::Both => quote! { #name: #ty; },
        PropertyKind::Get => quote! { #[get] #name: #ty; },
        PropertyKind::Set => quote! { #[set] #name: #ty; },
    }
}

fn write_event(name: &str, handler: &metadata::Type, namespace: &str) -> TokenStream {
    let name = write_ident(name);
    let handler = write_type(namespace, handler);
    quote! { event #name: #handler; }
